el></div><div class="usage-month">' + table('mois_chf') + '</div><div class="usage-total">' + table('total_chf') + '</div><p id="ia-swissnote-monthly-notice" style="margin-top:20px;font-size:14px;line-height:1.5">' + escape(swissNotice[l]) + '</p></section>';

